$g=@{};foreach($x in $gline.Split('|')[1..($gline.Split('|').Length-1)]){$kv=$x.Split('=',2);$g[$kv[0]]=$kv[1]}
$angles=foreach($line in $lines|Where-Object{$_.StartsWith('GRID_ANGLE|')}){$h=@{};foreach($x in $line.Split('|')[1..($line.Split('|').Length-1)]){$kv=$x.Split('=',2);$h[$kv[0]]=$kv[1]};[pscustomobject]@{angleDeg=[double]::Parse($h.angle,[cultureinfo]::InvariantCulture);cases=[int]$h.total;individualIncompatible=[int]$h.Aincompatible;individualNonpassive=[int]$h.Anonpassive;scaledReduced=[int]$h.Creduced;projectedReduced=[int]$h.Dreduced}}
$hash=(Get-FileHash PHASE3_MANIFOLD_RESTITUTION_LAWS_RAW_20261119.txt -Algorithm SHA256).Hash.ToLower();$repeat=(Get-FileHash PHASE3_MANIFOLD_RESTITUTION_LAWS_REPEAT_20261119.txt -Algorithm SHA256).Hash.ToLower()
$records=$lines|Where-Object{$_.StartsWith('FOCUS17994|') -or $_.StartsWith('FOCUS17994E1|') -or $_.StartsWith('ISOLATED|') -or $_.StartsWith('OPPOSED180|') -or $_.StartsWith('TWO_BODY_SINGLE|') -or $_.StartsWith('MIXED|') -or $_.StartsWith('MIXED_COMMON|') -or $_.StartsWith('PERMUTATION|')}
$doc=[ordered]@{schemaVersion=1;runtime=[ordered]@{name='Official standalone Luau CLI';version='0.747';exeSha256='ff0acf7d2df9d38e30c85ee9fe698efd756a920496c84ea848b74d0e2082e958';physicalRobloxTest=$false;nodeTest=$false};grid=[ordered]@{cases=[int]$g.cases;anglesDeg=@(90,120,150,170,175,179,179.94,180);velocities=@(@(20,0),@(20,-10),@(0,-10));restitutions=@(0,.5,1);constraintCounts=@(1,2,3,4);orders=@('canonical','reverseIds');budgetLabels=@(16,32,64,128);relaxationLabels=@(.5,.8,1,1.2,1.5);candidateSolutionsDoNotDependOnBudgetLabels=$true};candidateTotals=[ordered]@{A=[ordered]@{feasible=[int]$g.Afeasible;incompatible=[int]$g.Aincompatible;nonpassive=[int]$g.Anonpassive;maxEnergyRise=[double]::Parse($g.AmaxEnergyRise,[cultureinfo]::InvariantCulture)};B=[ordered]@{feasible=[int]$g.Bfeasible;incompatible=[int]$g.Bincompatible;nonpassive=[int]$g.Bnonpassive;maxEnergyRise=[double]::Parse($g.BmaxEnergyRise,[cultureinfo]::InvariantCulture);identicalToAOnUniformMaterials=$true};C=[ordered]@{valid=[int]$g.Cvalid;reduced=[int]$g.Creduced;inelasticFallback=[int]$g.CzeroFallback;maximumNumericalEnergyIncrease=[double]::Parse($g.CmaxEnergyRise,[cultureinfo]::InvariantCulture)};D=[ordered]@{valid=[int]$g.Dvalid;reduced=[int]$g.Dreduced;inelasticFallback=[int]$g.DzeroFallback;maximumEnergyIncrease=[double]::Parse($g.DmaxEnergyRise,[cultureinfo]::InvariantCulture)}};byAngle=@($angles);directRecords=@($records);materialRule='No surface bCoef combination rule was inferred. Contact-level e_i values are explicit; e_M is tested only as an external parameter.';determinism=[ordered]@{runs=2;sha256=$hash;repeatSha256=$repeat;byteIdentical=($hash -eq $repeat)};oracle='Independent exhaustive active-set enumeration; D additionally enumerates affine gamma intervals and the quadratic energy-passivity bound.'}
$out=$doc|ConvertTo-Json -Depth 12;[System.IO.File]::WriteAllText((Join-Path (Get-Location) 'PHASE3_MANIFOLD_RESTITUTION_LAWS_RESULTS_20261119.json'),$out,[System.Text.UTF8Encoding]::new($false))